INSERT INTO `narasi` VALUES (1,'<p align=\"center\" style=\"margin-top:0cm;margin-right:0cm;margin-bottom:7.5pt;\r\nmargin-left:0cm;text-align:center\"><span style=\"font-size: 10.5pt; font-family: Tahoma, &quot;sans-serif&quot;; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">﻿</span>﻿<b style=\"text-decoration-line: underline;\"><span style=\"font-family: Verdana, &quot;sans-serif&quot;; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">#NARASI</span></b><span style=\"font-size: 10.5pt; font-family: Helvetica, &quot;sans-serif&quot;;\"><o:p></o:p></span></p><p align=\"center\" style=\"margin: 0cm 0cm 7.5pt; text-align: center;\"><span style=\"font-family: Verdana, &quot;sans-serif&quot;; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">SELAMAT\r\nBERGABUNG DI JARINGAN DOKUMENTASI DAN INFORMASI HUKUM KOTA KENDARI.</span><span style=\"font-size: 10.5pt; font-family: Helvetica, &quot;sans-serif&quot;; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><br>\r\n<!--[if !supportLineBreakNewLine]--><br>\r\n<!--[endif]--></span><span style=\"font-size: 10.5pt; font-family: Helvetica, &quot;sans-serif&quot;;\"></span><o:p></o:p></p><p align=\"center\" style=\"margin: 0cm 0cm 7.5pt; text-align: center;\"><span style=\"font-family: Verdana, &quot;sans-serif&quot;; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">KAMI SENANTIASA&nbsp; BERKOMITMEN MEMBERIKAN\r\nSAJIAN INFORMASI HUKUM DENGAN AKSES CEPAT, MUDAH DAN TERKINI KEPADA STAKEHOLDER\r\nMASYARAKAT KOTA KENDARI, PENGUSAHA, LSM/ORMAS/PERKUMPULAN,\r\nINSTANSI/LEMBAGA/BADAN PEMERINTAHAN LAINNYA, DAN SKPD DI LINGKUNGAN PEMERINTAH\r\nKOTA KENDARI.<span style=\"font-family: &quot;Courier New&quot;; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">&nbsp;</span></span><span style=\"font-size: 10.5pt; font-family: Helvetica, &quot;sans-serif&quot;;\"><o:p></o:p></span></p><p align=\"center\" style=\"margin: 0cm 0cm 7.5pt; text-align: center;\"><b><span style=\"font-family: Verdana, &quot;sans-serif&quot;; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">#FIKSI HUKUM</span></b><span style=\"font-size: 10.5pt; font-family: Helvetica, &quot;sans-serif&quot;;\"><o:p></o:p></span></p><p align=\"center\" style=\"margin: 0cm 0cm 7.5pt; text-align: center;\"><span lang=\"IN\" style=\"font-family: Verdana, &quot;sans-serif&quot;; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Asas&nbsp;<i>Exeptio\r\nFormat Regulam / Exeptio Frimat Vim Legis In Casibus Non&nbsp;</i></span><i><span style=\"font-family: Verdana, &quot;sans-serif&quot;; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">E</span></i><i><span lang=\"IN\" style=\"font-family: Verdana, &quot;sans-serif&quot;; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">xceptis</span></i><b><span style=\"font-family: Arial, &quot;sans-serif&quot;; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"></span><br>\r\n<!--[if !supportLineBreakNewLine]--><br>\r\n<!--[endif]--></b><span style=\"font-size: 10.5pt; font-family: Helvetica, &quot;sans-serif&quot;;\"></span><o:p></o:p></p><p align=\"center\" style=\"margin: 0cm 0cm 7.5pt; text-align: center;\"><span style=\"text-decoration-line: underline;\"><b><span style=\"font-family: Verdana, &quot;sans-serif&quot;; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">#QUOTE</span></b></span><span style=\"font-size: 10.5pt; font-family: Helvetica, &quot;sans-serif&quot;; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><br>\r\n<!--[if !supportLineBreakNewLine]--><br>\r\n<!--[endif]--></span><span style=\"font-size: 10.5pt; font-family: Helvetica, &quot;sans-serif&quot;;\"></span><o:p></o:p></p><p align=\"center\" style=\"margin: 0cm 0cm 7.5pt; text-align: center;\"><span style=\"font-family: Verdana, &quot;sans-serif&quot;; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">HUKUM ITU MENSEJAHTERAHKAN DAN MEMBAHAGIAKAN&nbsp;</span><span style=\"font-family: Verdana, &quot;sans-serif&quot;; background-image: initial; backgroun