INSERT INTO `pembentukan_puu` VALUES (5,'naskah_akademik','NASKAH AKADEMIK RANCANGAN PERATURAN DAERAH TENTANG TATA CARA PENYELENGGARAAN CADANGAN PANGAN',NULL,2025,'Dinas Ketahanan Pangan','draft','pra_legislasi',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Abstrak Naskah Akademik Rancangan Peraturan Daerah Kota Kendari tentang Tata Cara Penyelenggaraan Cadangan Pangan.\r\n\r\nKota Kendari yang berada pada posisi yang strategis yang luas yang terdiri dari banyak Kecamatan dan Kelurahan serta memiliki banyak penduduk sangat mungkin terjadi kerawanan ketersediaan stok pangan, sehingga perlu perencanaan cadangan pangan yang diatur dalam suatu Peraturan Daerah sebagai dasar landasan hukum yang kuat.\r\nUntuk menindaklanjuti ketentuan Pasal 20 PP No.15 Tahun 2017 tentang Ketahanan Pangan maka perlu adanya upaya yang dilakukan Pemerintah Kota Kendari guna mengatasi permasalaham dan memberikan arah pengelolaan pangan melalui pembentukan suatu produk kebijakan berupa peraturan daerah sebagai landasan hukum bagi stakeholder terkait di dalam pelaksanaan di lapangan.\r\nPengaturan mengenai tata cara penyelenggaraan pangan di Kota Kendari diarahkan pada pengadaan pangan, pengelolaan pangan, penyaluran pangan, dan penanggulangan krisis pangan serta peran serta masyarakat sesuai dengan kewenangan Pemerintah Kota sebagaiman terdapat dalam Peraturan Pemerintah No. 15 Tahun 2017 tentang Ketahanan Pangan.\r\nSasaran yang akan diwujudkan, ruang lingkup pengaturan, jangkauh dan arah pengaturan rancangan Peraturan Daerah Kota Kendari tentang Tata Cara Penyelenggaraan Cadangan Pangan terdiri dari penetapan cadangan pangan, penyelenggaraan cadangan pangan, pengadaaan cadangan pangan, pengelolaan cadangan pangan, penyaluran cadangan pangan, penanggulangan krisis pangan, peran serta masyarakat, pengawasan dan pelaporan serta pendanaan.','Penyelenggaraan Cadangan Pangan, Naskah Akademik','Tim Dinas Ketahanan Pangan','Tim Dinas Ketahanan Pangan','pembentukan-puu/dokumen/YAw1Eg4K2uslexWXfH9jw6HzlYAGoxQw5gVcQiyw.pdf',NULL,NULL,'published','public','kajian',NULL,'Sukriati La Mbadjo','2025-12-29',366,135,'2026-01-22 11:20:19','2026-07-17 13:07:15',NULL),(6,'naskah_akademik','NASKAH KETERANGAN DAN/ATAU PENJELASAN RANCANGAN PERATURAN DAERAH TENTANG PERUBAHAN ATAS PERATURAN DAERAH KOTA KENDARI NOMOR 3 TAHUN 2018 TENTANG PENGELOLAAN BARANG MILIK DAERAH','-',2025,'BADAN KEUANGAN DAN ASET DAERAH KOTA KENDARI','draft','penyusunan_ruu',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Abstrak  Naskah Keterangan Dan/Atau Penjelasan Rancangan Peraturan Daerah tentang Perubahan Atas Peraturan Daerah Kota Kendari Nomor 3 Tahun 2018 tentang Pengelolaan Barang Milik Daerah\r\n\r\nBarang Milik Daerah sebagai salah satu unsur penting dalam rangka penyelenggaraan pemerintahan daerah dan pelayanan masyarakat harus dikelola dengan baik dan benar, yang pada gilirannya dapat mewujudkan pengelolaan Barang Milik Daerah dengan memperhatikan asas-asas sebagai berikut : asas fungsional, asas lepastian hukum, asas transparansi, asas efisiensi, asas akuntabilitas dan asas kepastgian nilai.\r\nPengelolaan Barang Milik Daerah meliputi perencanaan kebutuhan dan penganggaran, pengadaan, penggunaan, peamanfaatan, pengamanan dan pemeliharaan, penilaian, pemindahtanganan, pemusnahan, penghapusan, penatausahaan, dan pembinaan, pengawasan dan pengendalian.','Pengelolaan Barang Milik Daerah, Naskah Keterangan Dan/Atau Penjelasan','Tim BKAD Kota Kendari','BKAD Kota Kendari','pembentukan-puu/dokumen/l5aXsrqcxqRZ4T5SDXOkhgez7vr4RpjzVRrMy7PZ.pdf',NULL,NULL,'published','public','evaluasi',NULL,'Sukriati La Mbadjo','2025-12-15',61,118,'2026-01-22 12:05:43','2026-07-16 18:20:21',NULL),(8,'rancangan_puu','RANCANGAN PERATURAN WALI KOTA KENDARI TENTANG RENCANA INDUK DAN PETA JALAN PEMAJUAN ILMU PENGETAHUAN DAN TEKNOLOGI TAHUN 2025-2030',NULL,2026,'BADAN PERENCANAAN PEMBANGUNAN DAERAH KOTA KENDARI','final','penyusunan_ruu',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Dalam rangka meningkatkan kualitas pembangunan daerah Kota Kendari serta mendorong penyusunan kebijakan berbasis bukti, diperlukan perencanaan pembangunan yang mengintegrasikan ilmu pengetahuan dan teknologi, riset dan inovasi sebagai landasan ilmiah dalam perumusan kebijakan daerah; Untuk memperkuat ekosistem riset dan inovasi di Kota Kendari, diperlukan tata kelola riset dan inovasi daerah ytang terarah, terpadu, dan berkelanjutan melaluyi penyusunan Rencana Induk dan Peta Jalan Pemajuan Ilmu Pengetahuan dan Teknologi Tahun 2025-2030; Berdasarkan ketentuan Pasal 28 ayat (2) Peraturan badan Riset dan Inovasi Nasional nomor 5 Tahun 2023 tentang Tata Kelola Riset dan Inovasi di Daerah, Rencana Induk dan Peta Jalan Pemajuan Ilmu Pengetahuan dan Teknologi ditetapkan dengan Peraturan Walikota; Untuk itu perlu menetapkan Peraturan Walikota tentang Rencana Induk dan Peta jalan Pemajuan Ilmu Pengetahuan dan Teknologi Tahun 2025-2030.','Pemajuan IPTEK, Peta Jalan','Tim Bappeda','Bappeda','pembentukan-puu/dokumen/2sOeWysyVmPvBqbezcYDLTxwSkbDrPbsJneWp7yr.pdf',NULL,NULL,'published','public','pembentukan',NULL,'Sukriati La Mbadjo','2026-02-12',25,32,'2026-03-12 09:37:35','2026-07-17 14:55:16',NULL),(9,'rancangan_puu','RANCANGAN PERATURAN WALI KOTA KENDARI TENTANG TAMBAHAN PENGHASILAN APARATUR SIPIL NEGARA DI LINGKUNGAN PEMERINTAH DAERAH',NULL,2026,'BADAN KEPEGAWAIAN PENGEMBANGAN SUMBER DAYA MANUSIA','final','penyusunan_ruu',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Untuk melaksanakan ketentuan Pasal 58 ayat (3) Peraturan Pemerintah Nomor 12 Tahun 2019 tentang Pengelolaan Keuangan Daerah pemberian tambahan penghasilan kepada Aparatur Sipil Negara ditetapkan dengan peraturan Kepala Daerah','Aparatur Sipil Negara, Tambahan Penghasilan','Tim BKPSDM','Tim BKPSDM','pembentukan-puu/dokumen/oeOqNyWGfEIE7223udTvifyJ80XKfONZk1qcVLua.pdf',NULL,NULL,'published','public','pembentukan',NULL,'Sukriati La Mbadjo','2026-02-12',158,28,'2026-03-12 09:52:22','2026-07-17 14:55:15',NULL),(10,'naskah_akademik','NASKAH AKADEMIK PENYELENGGARAAN PENANGGULANGAN BENCANA',NULL,2026,'BADAN PENANGGULANGAN BENCANA DAERAH KOTA KENDARI','final','pra_legislasi',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'PENYELENGGARAAN PENANGGULANGAN BENCANA\r\n\r\nBahwa Pemerintah Daerah Bertanggungjawab menberikan perlindungan terhadap kehidupan dan penghidupan termasuk perlindungan atas bencana, dalam rangka mewujudkan kesejahteraan umum. Upaya penanggulangan bencana memberikan perlindungan dan hak atas rasa aman kepada masyarakat Kota Kendari dari anacaman bencana dan menjamin terselenggaranya penanggulangan bencana mulai dari prabencana, saat tanggap darurat, dan pasca bencana. Pemerintah Daerah berwenang nebetapkan penyelenggaraan penanggulangan bencana sesuai dengan ketentuan Undang-Undang Nomor 24 Tahun 2007 tentang Penanggulangan Bencana secara sistematis, terencana, terpadu.','Penanggulangan Bencana','Tim BPBD',NULL,'pembentukan-puu/dokumen/0P9IXWWZUzV9PSWZGKi87KMN0gH4eOSBBYbSvDEs.pdf',NULL,'pembentukan-puu/lampiran/xe13TUj4TVFMsdRAGU5cywloxih9l6vdbyZlhel4.pdf','published','public','penelitian','Laporan Akhir Naskah Akademik Penyelenggaraan Penanggulangan Bencana','Sukriati La Mbadjo','2026-06-10',53,50,'2026-06-10 14:23:54','2026-07-16 17:03:59',NULL);
